const CACHE_NAME = "eduzone-v1";
const STATIC_ASSETS = [
  "/",
  "/index.html",
  "/courses",
  "/quiz",
  "/dashboard",
  "/pricing",
  "/instructors",
];

// Install — cache static assets
self.addEventListener("install", (e) => {
  e.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(STATIC_ASSETS))
  );
  self.skipWaiting();
});

// Activate — clean old caches
self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
    )
  );
  self.clients.claim();
});

// Fetch — network first, cache fallback
self.addEventListener("fetch", (e) => {
  if (e.request.method !== "GET") return;
  if (e.request.url.includes("firestore") || e.request.url.includes("firebase")) return;

  e.respondWith(
    fetch(e.request)
      .then((res) => {
        const clone = res.clone();
        caches.open(CACHE_NAME).then((cache) => cache.put(e.request, clone));
        return res;
      })
      .catch(() => caches.match(e.request))
  );
});

// Push notifications
self.addEventListener("push", (e) => {
  const data = e.data?.json() || {};
  e.waitUntil(
    self.registration.showNotification(data.title || "EduZone", {
      body: data.body || "Yangi xabar bor!",
      icon: "/icons/icon-192.png",
      badge: "/icons/icon-192.png",
      data: { url: data.url || "/" },
    })
  );
});

self.addEventListener("notificationclick", (e) => {
  e.notification.close();
  e.waitUntil(clients.openWindow(e.notification.data?.url || "/"));
});

import React, { useState, useEffect } from "react";
import { BiLogoReact } from "react-icons/bi";
import { Link, NavLink } from "react-router-dom";
import { HiMenu, HiX } from "react-icons/hi";
import { useLang } from "../context/useLang";
import { useAuth } from "../context/useAuth";
import { doc, getDoc } from "firebase/firestore";
import { db } from "../firebase/config";

const navLinks = [
  { path: "/", label: "🎓 Kurslar", end: true },
  { path: "/instructors", label: "👨‍🏫 O'qituvchilar", end: false },
  { path: "/pricing", label: "💎 Narxlar", end: false },
];

// Unread notif count (demo)
const UNREAD = 3;

const Navbar = ({ darkMode, setDarkMode, onNavClick }) => {
  const { lang, setLang } = useLang();
  const { user, logout } = useAuth();
  const [menuOpen, setMenuOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [langOpen, setLangOpen] = useState(false);

  const langs = [
    { code: "uz", flag: "🇺🇿", label: "UZ" },
    { code: "en", flag: "🇬🇧", label: "EN" },
  ];
  const currentLang = langs.find((l) => l.code === lang) || langs[0];

  useEffect(() => {
    const checkAdmin = async () => {
      if (!user) { setIsAdmin(false); return; }
      const snap = await getDoc(doc(db, "admins", user.uid));
      setIsAdmin(snap.exists() && snap.data().isAdmin === true);
    };
    checkAdmin();
  }, [user]);

  const sidebarLinks = [
    { path: "/dashboard", label: "📊 Dashboard" },
    { path: "/quiz", label: "🎯 Quiz" },
    { path: "/notifications", label: "🔔 Bildirishnomalar" },
    { path: "/chat", label: "💬 Chat" },
    { path: "/dm", label: "✉️ DM" },
    { path: "/story", label: "📸 Story" },
    { path: "/games", label: "🎮 Games" },
    { path: "/code", label: "💻 Code" },
    { path: "/typing", label: "⌨️ Typing" },
    { path: "/multiplayer", label: "👥 Multi" },
    { path: "/profile", label: "👤 Profil" },
    ...(isAdmin ? [{ path: "/admin", label: "🛡️ Admin" }] : []),
  ];

  return (
    <>
      <nav className="bg-slate-800 shadow-lg fixed top-0 left-0 w-full z-50">
        <div className="flex items-center justify-between py-3 px-6">

          {/* Logo */}
          <Link to="/" onClick={onNavClick}>
            <span className="font-semibold text-lg flex items-center gap-3 text-blue-400">
              <BiLogoReact className="text-4xl md:text-5xl" />
              <span className="font-semibold text-lg md:text-xl">Uzbekas Pixel</span>
            </span>
          </Link>

          {/* Desktop nav */}
          <div className="hidden md:flex items-center gap-3">
            {navLinks.map((link) => (
              <NavLink key={link.path} to={link.path} end={link.end} onClick={onNavClick}
                className={({ isActive }) =>
                  `py-1 px-3 text-base font-light rounded-2xl transition duration-300 ${
                    isActive ? "text-sky-300 bg-slate-700" : "text-white hover:text-sky-300 hover:bg-slate-700"
                  }`
                }>
                {link.label}
              </NavLink>
            ))}

            {/* Notifications bell */}
            <NavLink to="/notifications" onClick={onNavClick} style={{ position: "relative" }}
              className={({ isActive }) =>
                `py-1 px-2 rounded-xl transition duration-300 flex items-center ${
                  isActive ? "text-sky-300 bg-slate-700" : "text-white hover:text-sky-300 hover:bg-slate-700"
                }`
              }>
              <span style={{ fontSize: 20 }}>🔔</span>
              {UNREAD > 0 && (
                <span style={{
                  position: "absolute", top: -2, right: -2,
                  background: "#ef4444", color: "#fff",
                  fontSize: 9, fontWeight: 700, padding: "1px 5px",
                  borderRadius: 10, lineHeight: 1.4,
                }}>{UNREAD}</span>
              )}
            </NavLink>

            {/* Language dropdown */}
            <div style={{ position: "relative" }}>
              <button
                onClick={() => setLangOpen(!langOpen)}
                onBlur={() => setTimeout(() => setLangOpen(false), 150)}
                className="py-1 px-3 text-sm font-semibold text-white border border-slate-500 rounded-xl hover:bg-slate-700 transition duration-300 flex items-center gap-1"
              >
                {currentLang.flag} {currentLang.label} <span style={{ fontSize: 10 }}>▾</span>
              </button>
              {langOpen && (
                <div style={{
                  position: "absolute", top: "calc(100% + 6px)", right: 0,
                  background: "#1e293b", border: "1px solid #334155",
                  borderRadius: 10, overflow: "hidden", zIndex: 200, minWidth: 100,
                  boxShadow: "0 8px 24px rgba(0,0,0,0.3)",
                }}>
                  {langs.map((l) => (
                    <button key={l.code} onClick={() => { setLang(l.code); setLangOpen(false); }}
                      style={{
                        display: "flex", alignItems: "center", gap: 8,
                        width: "100%", padding: "9px 14px", background: "none", border: "none",
                        cursor: "pointer", fontSize: 13, fontWeight: 600,
                        color: lang === l.code ? "#60a5fa" : "#e2e8f0",
                        background: lang === l.code ? "#334155" : "transparent",
                      }}>
                      {l.flag} {l.label}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Dark mode */}
            <div onClick={() => setDarkMode(!darkMode)} className="relative w-8 h-8 overflow-hidden cursor-pointer">
              <span className="absolute inset-0 flex items-center justify-center text-2xl transition-all duration-500"
                style={{ transform: darkMode ? "translateY(100%)" : "translateY(0%)", opacity: darkMode ? 0 : 1 }}>☀️</span>
              <span className="absolute inset-0 flex items-center justify-center text-2xl transition-all duration-500"
                style={{ transform: darkMode ? "translateY(0%)" : "translateY(-100%)", opacity: darkMode ? 1 : 0 }}>🌙</span>
            </div>

            {/* User */}
            {user ? (
              <button onClick={logout}
                className="py-1 px-3 text-sm text-red-400 border border-red-400 rounded-xl hover:bg-red-400 hover:text-white transition duration-300">
                Chiqish
              </button>
            ) : (
              <Link to="/login" onClick={onNavClick}
                className="py-1 px-3 text-sm font-semibold text-white bg-blue-500 hover:bg-blue-400 rounded-xl transition duration-300">
                Kirish
              </Link>
            )}

            <button onClick={() => setSidebarOpen(true)}
              className="w-9 h-9 bg-slate-700 hover:bg-slate-600 text-white rounded-xl flex items-center justify-center text-lg transition">
              ›
            </button>
          </div>

          {/* Mobile controls */}
          <div className="flex md:hidden items-center gap-3">
            <NavLink to="/notifications" style={{ position: "relative", color: "#fff", fontSize: 20 }}>
              🔔
              {UNREAD > 0 && (
                <span style={{
                  position: "absolute", top: -4, right: -4,
                  background: "#ef4444", color: "#fff",
                  fontSize: 9, fontWeight: 700, padding: "1px 4px", borderRadius: 8,
                }}>{UNREAD}</span>
              )}
            </NavLink>
            <div onClick={() => setDarkMode(!darkMode)} className="relative w-8 h-8 overflow-hidden cursor-pointer">
              <span className="absolute inset-0 flex items-center justify-center text-2xl transition-all duration-500"
                style={{ transform: darkMode ? "translateY(100%)" : "translateY(0%)", opacity: darkMode ? 0 : 1 }}>☀️</span>
              <span className="absolute inset-0 flex items-center justify-center text-2xl transition-all duration-500"
                style={{ transform: darkMode ? "translateY(0%)" : "translateY(-100%)", opacity: darkMode ? 1 : 0 }}>🌙</span>
            </div>
            <button onClick={() => setMenuOpen(!menuOpen)} className="text-white text-3xl">
              {menuOpen ? <HiX /> : <HiMenu />}
            </button>
          </div>
        </div>

        {/* Mobile menu */}
        <div className={`md:hidden bg-slate-800 overflow-hidden transition-all duration-300 ${menuOpen ? "max-h-[500px] py-3" : "max-h-0"}`}>
          {navLinks.map((link) => (
            <NavLink key={link.path} to={link.path} end={link.end}
              onClick={() => { onNavClick(); setMenuOpen(false); }}
              className={({ isActive }) =>
                `block py-2 px-8 text-lg font-light transition duration-300 ${
                  isActive ? "text-sky-300 bg-slate-700 font-semibold" : "text-white hover:text-sky-300 hover:bg-slate-700"
                }`
              }>
              {link.label}
            </NavLink>
          ))}
          {/* Lang options mobile */}
          <div className="px-8 py-2 flex gap-2">
            {langs.map((l) => (
              <button key={l.code} onClick={() => setLang(l.code)}
                className={`text-xs font-semibold border px-2 py-1 rounded-lg transition ${
                  lang === l.code ? "bg-blue-500 text-white border-blue-500" : "text-white border-slate-500"
                }`}>
                {l.flag} {l.label}
              </button>
            ))}
          </div>
          {isAdmin && (
            <NavLink to="/admin" onClick={() => { onNavClick(); setMenuOpen(false); }}
              className={({ isActive }) => `block py-2 px-8 text-lg font-light transition duration-300 ${isActive ? "text-yellow-300 bg-slate-700" : "text-yellow-400 hover:bg-slate-700"}`}>
              🛡️ Admin
            </NavLink>
          )}
          <div className="px-8 py-3 border-t border-slate-700 mt-2">
            {user ? (
              <>
                <Link to="/profile" onClick={() => { onNavClick(); setMenuOpen(false); }}
                  className="flex items-center gap-3 mb-3 hover:opacity-80 transition">
                  <div className="w-10 h-10 rounded-full bg-blue-500 flex items-center justify-center text-white font-bold overflow-hidden border-2 border-blue-400">
                    {user.photoURL ? <img src={user.photoURL} alt="avatar" className="w-full h-full object-cover" /> : user.displayName?.[0]?.toUpperCase() || user.email?.[0]?.toUpperCase()}
                  </div>
                  <div>
                    <p className="text-white text-sm font-semibold">{user.displayName || "Foydalanuvchi"}</p>
                    <p className="text-gray-400 text-xs">{user.email}</p>
                  </div>
                </Link>
                <button onClick={() => { logout(); setMenuOpen(false); }}
                  className="text-sm text-red-400 border border-red-400 px-3 py-1 rounded-xl hover:bg-red-400 hover:text-white transition">
                  Chiqish
                </button>
              </>
            ) : (
              <Link to="/login" onClick={() => { onNavClick(); setMenuOpen(false); }}
                className="block text-lg font-light text-blue-400 hover:text-blue-300 transition">
                Kirish
              </Link>
            )}
          </div>
        </div>
      </nav>

      {/* Desktop Sidebar */}
      <>
        {sidebarOpen && (
          <div className="hidden md:block fixed inset-0 z-[998] bg-black/40" onClick={() => setSidebarOpen(false)} />
        )}
        <div className={`hidden md:flex fixed top-0 right-0 h-full z-[999] flex-col w-64 transition-transform duration-300 shadow-2xl ${
          darkMode ? "bg-slate-900" : "bg-white"
        } ${sidebarOpen ? "translate-x-0" : "translate-x-full"}`}>
          <div className="flex items-center justify-between px-5 py-4 border-b border-slate-700">
            <span className={`font-bold text-lg ${darkMode ? "text-white" : "text-gray-900"}`}>Menyu</span>
            <button onClick={() => setSidebarOpen(false)}
              className={`w-8 h-8 rounded-xl flex items-center justify-center transition ${darkMode ? "bg-slate-700 text-white hover:bg-slate-600" : "bg-gray-100 text-gray-600 hover:bg-gray-200"}`}>✕</button>
          </div>
          <div className="flex-1 overflow-y-auto py-3">
            {sidebarLinks.map((link) => (
              <NavLink key={link.path} to={link.path}
                onClick={() => { onNavClick(); setSidebarOpen(false); }}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-5 py-3 text-sm font-medium transition ${
                    isActive
                      ? darkMode ? "bg-slate-700 text-blue-400" : "bg-blue-50 text-blue-500"
                      : darkMode ? "text-gray-300 hover:bg-slate-700" : "text-gray-700 hover:bg-gray-50"
                  }`
                }>
                {link.label}
              </NavLink>
            ))}
          </div>
          {user && (
            <div className={`px-5 py-4 border-t ${darkMode ? "border-slate-700" : "border-gray-200"}`}>
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 rounded-full bg-blue-500 flex items-center justify-center text-white font-bold overflow-hidden border-2 border-blue-400 shrink-0">
                  {user.photoURL ? <img src={user.photoURL} alt="" className="w-full h-full object-cover" /> : user.displayName?.[0]?.toUpperCase() || "?"}
                </div>
                <div className="min-w-0">
                  <p className={`text-sm font-semibold truncate ${darkMode ? "text-white" : "text-gray-900"}`}>{user.displayName || "Foydalanuvchi"}</p>
                  <p className={`text-xs truncate ${darkMode ? "text-gray-400" : "text-gray-500"}`}>{user.email}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </>
    </>
  );
};

export default Navbar;

