};

const Reviews = ({ darkMode }) => {
  const reviews = [
    { name: "Aziz T.", rating: 5, date: "2 kun oldin", text: "Juda yaxshi kurs! Hamma narsa tushunarli tushuntirilgan. Tavsiya qilaman." },
    { name: "Kamola R.", rating: 4, date: "1 hafta oldin", text: "Kurs materiallari sifatli, amaliy mashqlar juda foydali bo'ldi." },
    { name: "Sherzod M.", rating: 5, date: "2 hafta oldin", text: "O'qituvchi juda yaxshi tushuntiradi. Loyiha qismi ayniqsa foydali." },
  ];

  const [newReview, setNewReview] = useState({ rating: 5, text: "" });
  const [submitted, setSubmitted] = useState(false);
  const [allReviews, setAllReviews] = useState(reviews);

  const Stars = ({ rating, interactive = false, onChange }) => (
    <div style={{ display: "flex", gap: 3 }}>
      {[1,2,3,4,5].map((s) => (
        <span
          key={s}
          onClick={() => interactive && onChange && onChange(s)}
          style={{
            fontSize: interactive ? 24 : 14,
            color: s <= rating ? "#f59e0b" : "#d1d5db",
            cursor: interactive ? "pointer" : "default",
            transition: "transform 0.15s",
          }}
          onMouseEnter={(e) => interactive && (e.target.style.transform = "scale(1.2)")}
          onMouseLeave={(e) => interactive && (e.target.style.transform = "scale(1)")}
        >★</span>
      ))}
    </div>
  );

  const handleSubmit = () => {
    if (!newReview.text.trim()) return;
    setAllReviews([{ name: "Siz", rating: newReview.rating, date: "Hozirgina", text: newReview.text }, ...allReviews]);
    setSubmitted(true);
    setNewReview({ rating: 5, text: "" });
  };

  const avg = (allReviews.reduce((a, r) => a + r.rating, 0) / allReviews.length).toFixed(1);

  return (
    <div>
      {/* Summary */}
      <div style={{
        display: "flex", alignItems: "center", gap: 20, marginBottom: 24,
        padding: "16px 20px",
        background: darkMode ? "#1e293b" : "#f8fafc",
        borderRadius: 12, border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
      }}>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 40, fontWeight: 800, color: "#f59e0b", lineHeight: 1 }}>{avg}</div>
          <Stars rating={Math.round(avg)} />
          <div style={{ fontSize: 12, color: "#6b7280", marginTop: 4 }}>{allReviews.length} ta sharh</div>
        </div>
        <div style={{ flex: 1 }}>
          {[5,4,3,2,1].map((star) => {
            const count = allReviews.filter((r) => r.rating === star).length;
            const pct = Math.round((count / allReviews.length) * 100);
            return (
              <div key={star} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                <span style={{ fontSize: 12, color: "#6b7280", width: 16 }}>{star}</span>
                <span style={{ fontSize: 12, color: "#f59e0b" }}>★</span>
                <div style={{ flex: 1, height: 6, borderRadius: 3, background: darkMode ? "#334155" : "#e5e7eb" }}>
                  <div style={{ width: `${pct}%`, height: "100%", borderRadius: 3, background: "#f59e0b" }} />
                </div>
                <span style={{ fontSize: 12, color: "#6b7280", width: 28 }}>{pct}%</span>
              </div>
            );
          })}
        </div>
      </div>

      {/* Write review */}
      {!submitted ? (
        <div style={{
          marginBottom: 24, padding: "16px 20px",
          background: darkMode ? "#1e293b" : "#fff",
          borderRadius: 12, border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
        }}>
          <p style={{ margin: "0 0 10px", fontWeight: 600, fontSize: 14, color: darkMode ? "#f1f5f9" : "#111" }}>
            Sharh yozing
          </p>
          <Stars rating={newReview.rating} interactive onChange={(r) => setNewReview({ ...newReview, rating: r })} />
          <textarea
            rows={3}
            placeholder="Kurs haqida fikringiz..."
            value={newReview.text}
            onChange={(e) => setNewReview({ ...newReview, text: e.target.value })}
            style={{
              width: "100%", marginTop: 10, padding: "10px 12px",
              borderRadius: 8, border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
              background: darkMode ? "#0f172a" : "#f8fafc",
              color: darkMode ? "#f1f5f9" : "#111", fontSize: 13,
              resize: "none", outline: "none", boxSizing: "border-box",
            }}
          />
          <button
            onClick={handleSubmit}
            style={{
              marginTop: 8, padding: "8px 20px",
              background: "#3b82f6", color: "#fff",
              border: "none", borderRadius: 8,
              fontSize: 13, fontWeight: 600, cursor: "pointer",
            }}
          >
            Yuborish
          </button>
        </div>
      ) : (
        <div style={{
          marginBottom: 24, padding: "12px 16px",
          background: "#d1fae5", borderRadius: 10,
          fontSize: 13, color: "#065f46", fontWeight: 600,
        }}>
          ✅ Sharhingiz qabul qilindi!
        </div>
      )}

      {/* Reviews list */}
      {allReviews.map((r, i) => (
        <div key={i} style={{
          marginBottom: 14, padding: "14px 16px",
          background: darkMode ? "#1e293b" : "#fff",
          borderRadius: 12, border: `1px solid ${darkMode ? "#334155" : "#f3f4f6"}`,
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 6 }}>
            <div style={{
              width: 34, height: 34, borderRadius: "50%",
              background: "#3b82f6", color: "#fff",
              display: "flex", alignItems: "center", justifyContent: "center",
              fontWeight: 700, fontSize: 13,
            }}>
              {r.name[0]}
            </div>
            <div>
              <p style={{ margin: 0, fontWeight: 600, fontSize: 13, color: darkMode ? "#f1f5f9" : "#111" }}>{r.name}</p>
              <p style={{ margin: 0, fontSize: 11, color: "#6b7280" }}>{r.date}</p>
            </div>
            <div style={{ marginLeft: "auto" }}>
              <Stars rating={r.rating} />
            </div>
          </div>
          <p style={{ margin: 0, fontSize: 13, color: darkMode ? "#94a3b8" : "#4b5563", lineHeight: 1.6 }}>{r.text}</p>
        </div>
      ))}
    </div>
  );
};

const PaymentModal = ({ course, onClose, onSuccess, darkMode }) => {
  const [step, setStep] = useState(1);
  const [method, setMethod] = useState("card");
  const [cardNum, setCardNum] = useState("");
  const [loading, setLoading] = useState(false);

  const formatCard = (val) => {
    const digits = val.replace(/\D/g, "").slice(0, 16);
    return digits.replace(/(.{4})/g, "$1 ").trim();
  };

  const handlePay = () => {
    if (cardNum.replace(/\s/g, "").length < 16) return;
    setLoading(true);
    setTimeout(() => { setLoading(false); setStep(3); }, 2000);
  };

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, zIndex: 1000,
        background: "rgba(0,0,0,0.7)",
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: 16,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "100%", maxWidth: 420,
          borderRadius: 18, overflow: "hidden",
          background: darkMode ? "#1e293b" : "#fff",
          boxShadow: "0 24px 64px rgba(0,0,0,0.4)",
        }}
      >
        {/* Header */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "16px 20px",
          borderBottom: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
        }}>
          <p style={{ margin: 0, fontWeight: 700, fontSize: 15, color: darkMode ? "#f1f5f9" : "#111" }}>
            {step === 3 ? "✅ To'lov muvaffaqiyatli" : "💳 To'lov"}
          </p>
          <button onClick={onClose} style={{ background: "none", border: "none", cursor: "pointer", fontSize: 18, color: "#6b7280" }}>✕</button>
        </div>

        <div style={{ padding: "20px" }}>
          {step === 1 && (
            <>
              {/* Course summary */}
              <div style={{
                padding: "12px 14px", borderRadius: 10, marginBottom: 18,
                background: darkMode ? "#0f172a" : "#f8fafc",
                border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
              }}>
                <p style={{ margin: "0 0 4px", fontWeight: 600, fontSize: 14, color: darkMode ? "#f1f5f9" : "#111" }}>{course.title}</p>
                <p style={{ margin: 0, fontSize: 12, color: "#6b7280" }}>👤 {course.instructor}</p>
                <p style={{ margin: "8px 0 0", fontWeight: 800, fontSize: 20, color: "#3b82f6" }}>
                  {course.price.toLocaleString()} so'm
                </p>
              </div>

              {/* Payment method */}
              <p style={{ margin: "0 0 10px", fontWeight: 600, fontSize: 13, color: darkMode ? "#94a3b8" : "#6b7280" }}>To'lov usuli</p>
              <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
                {[
                  { id: "card", label: "💳 Karta" },
                  { id: "payme", label: "🟢 Payme" },
                  { id: "click", label: "🔵 Click" },
                ].map((m) => (
                  <button
                    key={m.id}
                    onClick={() => setMethod(m.id)}
                    style={{
                      flex: 1, padding: "9px 0", borderRadius: 8,
                      border: `2px solid ${method === m.id ? "#3b82f6" : darkMode ? "#334155" : "#e5e7eb"}`,
                      background: method === m.id ? (darkMode ? "#1e3a5f" : "#eff6ff") : "transparent",
                      color: method === m.id ? "#3b82f6" : darkMode ? "#94a3b8" : "#374151",
                      fontSize: 12, fontWeight: 600, cursor: "pointer",
                    }}
                  >
                    {m.label}
                  </button>
                ))}
              </div>

              <button
                onClick={() => setStep(2)}
                style={{
                  width: "100%", padding: "12px 0",
                  background: "#3b82f6", color: "#fff",
                  border: "none", borderRadius: 10,
                  fontSize: 14, fontWeight: 700, cursor: "pointer",
                }}
              >
                Davom etish →
              </button>
            </>
          )}

          {step === 2 && (
            <>
              <p style={{ margin: "0 0 14px", fontWeight: 600, fontSize: 13, color: darkMode ? "#94a3b8" : "#6b7280" }}>
                Karta ma'lumotlari
              </p>
              <div style={{ display: "flex", flexDirection: "column", gap: 10, marginBottom: 18 }}>
                <input
                  placeholder="0000 0000 0000 0000"
                  value={cardNum}
                  onChange={(e) => setCardNum(formatCard(e.target.value))}
                  style={{
                    padding: "11px 14px", borderRadius: 8,
                    border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                    background: darkMode ? "#0f172a" : "#f8fafc",
                    color: darkMode ? "#f1f5f9" : "#111",
                    fontSize: 16, letterSpacing: "0.1em", outline: "none",
                  }}
                />
                <div style={{ display: "flex", gap: 8 }}>
                  <input placeholder="MM/YY" style={{
                    flex: 1, padding: "11px 14px", borderRadius: 8,
                    border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                    background: darkMode ? "#0f172a" : "#f8fafc",
                    color: darkMode ? "#f1f5f9" : "#111", fontSize: 14, outline: "none",
                  }} />
                  <input placeholder="CVV" maxLength={3} style={{
                    width: 80, padding: "11px 14px", borderRadius: 8,
                    border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                    background: darkMode ? "#0f172a" : "#f8fafc",
                    color: darkMode ? "#f1f5f9" : "#111", fontSize: 14, outline: "none",
                  }} />
                </div>
              </div>

              <div style={{
                display: "flex", justifyContent: "space-between",
                padding: "10px 14px", borderRadius: 8, marginBottom: 14,
                background: darkMode ? "#0f172a" : "#f8fafc",
              }}>
                <span style={{ fontSize: 13, color: "#6b7280" }}>Jami:</span>
                <span style={{ fontSize: 14, fontWeight: 800, color: "#3b82f6" }}>
                  {course.price.toLocaleString()} so'm
                </span>
              </div>

              <button
                onClick={handlePay}
                disabled={loading}
                style={{
                  width: "100%", padding: "12px 0",
                  background: loading ? "#93c5fd" : "#3b82f6",
                  color: "#fff", border: "none", borderRadius: 10,
                  fontSize: 14, fontWeight: 700, cursor: loading ? "default" : "pointer",
                }}
              >
                {loading ? "⏳ Tekshirilmoqda..." : `💳 ${course.price.toLocaleString()} so'm To'lash`}
              </button>
            </>
          )}

          {step === 3 && (
            <div style={{ textAlign: "center", padding: "10px 0" }}>
              <div style={{ fontSize: 56, marginBottom: 12 }}>🎉</div>
              <p style={{ fontWeight: 700, fontSize: 16, color: darkMode ? "#f1f5f9" : "#111", margin: "0 0 6px" }}>
                Tabriklaymiz!
              </p>
              <p style={{ fontSize: 13, color: "#6b7280", margin: "0 0 20px" }}>
                "{course.title}" kursiga muvaffaqiyatli yozildingiz!
              </p>
              <button
                onClick={() => { onSuccess(); onClose(); }}
                style={{
                  padding: "11px 28px",
                  background: "#10b981", color: "#fff",
                  border: "none", borderRadius: 10,
                  fontSize: 14, fontWeight: 700, cursor: "pointer",
                }}
              >
                O'qishni boshlash →
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const CourseDetail = ({ courseId, onBack, darkMode, showToast }) => {
  const course = coursesData[courseId] || coursesData[1];
  const [activeTab, setActiveTab] = useState("lessons");
  const [openSections, setOpenSections] = useState([0]);
  const [purchased, setPurchased] = useState(course.price === 0);
  const [completedLessons, setCompletedLessons] = useState(course.price === 0 ? [1, 2] : []);
  const [showPayment, setShowPayment] = useState(false);

  const totalLessons = course.sections.reduce((a, s) => a + s.lessons.length, 0);
  const progress = Math.round((completedLessons.length / totalLessons) * 100);

  const toggleSection = (i) => {
    setOpenSections((prev) =>
      prev.includes(i) ? prev.filter((x) => x !== i) : [...prev, i]
    );
  };

  const toggleLesson = (id) => {
    if (!purchased) { setShowPayment(true); return; }
    setCompletedLessons((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    );
  };

  const tabs = ["lessons", "reviews", "faq"];
  const tabLabels = { lessons: "📚 Darslar", reviews: "⭐ Sharhlar", faq: "❓ FAQ" };

  const faqs = [
    { q: "Kursga qancha vaqt kirish mumkin?", a: "Sotib olgandan so'ng umrbod kirish imkoniyatiga ega bo'lasiz." },
    { q: "Sertifikat beriladimi?", a: "Ha, kursni 100% tugatgandan so'ng sertifikat yuklab olishingiz mumkin." },
    { q: "Qaytarish mumkinmi?", a: "30 kun ichida so'rasangiz, to'lovni qaytarib beramiz." },
    { q: "Mobil qurilmada o'qish mumkinmi?", a: "Ha, barcha qurilmalarda ishlaydi — telefon, planshet va kompyuter." },
    { q: "O'qituvchi bilan bog'lanish mumkinmi?", a: "Ha, har bir dars ostidagi izoh bo'limida savol berishingiz mumkin." },
  ];

  return (
    <div style={{ width: "100%", maxWidth: 900, margin: "0 auto", padding: "32px 20px 80px" }}>
      {/* Back */}
      <button
        onClick={onBack}
        style={{
          display: "flex", alignItems: "center", gap: 6,
          background: "none", border: "none", cursor: "pointer",
          color: "#3b82f6", fontSize: 14, fontWeight: 600, marginBottom: 20,
          padding: 0,
        }}
      >
        ← Kurslar katalogiga qaytish
      </button>

      {/* Thumbnail */}
      <ScrollReveal direction="up">
        <div style={{ borderRadius: 16, overflow: "hidden", marginBottom: 24, position: "relative" }}>
          <img src={course.thumbnail} alt={course.title} style={{ width: "100%", height: 260, objectFit: "cover", display: "block" }} />
          <div style={{
            position: "absolute", bottom: 0, left: 0, right: 0,
            background: "linear-gradient(transparent, rgba(0,0,0,0.7))",
            padding: "32px 24px 20px",
          }}>
            <span style={{
              background: course.color, color: "#fff",
              fontSize: 11, fontWeight: 700, padding: "3px 10px", borderRadius: 20,
            }}>{course.category}</span>
            <h1 style={{ color: "#fff", fontWeight: 800, fontSize: 24, margin: "8px 0 4px" }}>{course.title}</h1>
            <p style={{ color: "rgba(255,255,255,0.8)", fontSize: 13, margin: 0 }}>
              ⭐ {course.rating} · 👥 {course.students.toLocaleString()} talaba · ⏱ {course.duration} soat
            </p>
          </div>
        </div>
      </ScrollReveal>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
        {/* Left — main */}
        <div style={{ flex: "1 1 520px" }}>
          {/* Progress bar (if purchased) */}
          {purchased && (
            <ScrollReveal direction="up">
              <div style={{
                marginBottom: 20, padding: "16px 20px",
                background: darkMode ? "#1e293b" : "#fff",
                borderRadius: 12, border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
                  <span style={{ fontSize: 14, fontWeight: 600, color: darkMode ? "#f1f5f9" : "#111" }}>
                    O'quv progressi
                  </span>
                  <span style={{ fontSize: 14, fontWeight: 700, color: "#3b82f6" }}>{progress}%</span>
                </div>
                <div style={{ height: 8, borderRadius: 4, background: darkMode ? "#334155" : "#e5e7eb" }}>
                  <div style={{
                    height: "100%", borderRadius: 4,
                    background: progress === 100 ? "#10b981" : "#3b82f6",
                    width: `${progress}%`, transition: "width 0.4s ease",
                  }} />
                </div>
                <p style={{ margin: "8px 0 0", fontSize: 12, color: "#6b7280" }}>
                  {completedLessons.length} / {totalLessons} dars tugatildi
                  {progress === 100 && " 🎉 — Kursni tugatdingiz!"}
                </p>
                {progress === 100 && (
                  <button style={{
                    marginTop: 10, padding: "8px 18px",
                    background: "#10b981", color: "#fff",
                    border: "none", borderRadius: 8,
                    fontSize: 13, fontWeight: 700, cursor: "pointer",
                  }}>
                    🏆 Sertifikat yuklab olish
                  </button>
                )}
              </div>
            </ScrollReveal>
          )}

          {/* Tabs */}
          <div style={{ display: "flex", gap: 4, marginBottom: 20, borderBottom: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}` }}>
            {tabs.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                style={{
                  padding: "10px 16px", background: "none", border: "none",
                  cursor: "pointer", fontSize: 13, fontWeight: 600,
                  color: activeTab === tab ? "#3b82f6" : "#6b7280",
                  borderBottom: `2px solid ${activeTab === tab ? "#3b82f6" : "transparent"}`,
                  marginBottom: -1,
                }}
              >
                {tabLabels[tab]}
              </button>
            ))}
          </div>

          {/* Lessons tab */}
          {activeTab === "lessons" && (
            <div>
              <p style={{ margin: "0 0 14px", fontSize: 13, color: "#6b7280" }}>
                {course.sections.length} bo'lim · {totalLessons} dars
              </p>
              {course.sections.map((section, si) => (
                <div key={si} style={{ marginBottom: 8 }}>
                  <button
                    onClick={() => toggleSection(si)}
                    style={{
                      width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between",
                      padding: "12px 16px", borderRadius: 10,
                      background: darkMode ? "#1e293b" : "#f8fafc",
                      border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                      cursor: "pointer", textAlign: "left",
                    }}
                  >
                    <span style={{ fontWeight: 600, fontSize: 14, color: darkMode ? "#f1f5f9" : "#111" }}>
                      {openSections.includes(si) ? "▾" : "▸"} {section.title}
                    </span>
                    <span style={{ fontSize: 12, color: "#6b7280" }}>{section.lessons.length} dars</span>
                  </button>

                  {openSections.includes(si) && (
                    <div style={{
                      borderRadius: "0 0 10px 10px",
                      border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                      borderTop: "none", overflow: "hidden",
                    }}>
                      {section.lessons.map((lesson) => {
                        const done = completedLessons.includes(lesson.id);
                        const locked = !purchased && !lesson.free;
                        return (
                          <div
                            key={lesson.id}
                            onClick={() => !locked && toggleLesson(lesson.id)}
                            style={{
                              display: "flex", alignItems: "center", gap: 12,
                              padding: "11px 16px",
                              background: done ? (darkMode ? "#0f2818" : "#f0fdf4") : (darkMode ? "#0f172a" : "#fff"),
                              borderBottom: `1px solid ${darkMode ? "#1e293b" : "#f3f4f6"}`,
                              cursor: locked ? "default" : "pointer",
                              opacity: locked ? 0.6 : 1,
                              transition: "background 0.15s",
                            }}
                          >
                            <div style={{
                              width: 22, height: 22, borderRadius: "50%",
                              border: `2px solid ${done ? "#10b981" : locked ? "#9ca3af" : "#3b82f6"}`,
                              background: done ? "#10b981" : "transparent",
                              display: "flex", alignItems: "center", justifyContent: "center",
                              fontSize: 11, color: done ? "#fff" : locked ? "#9ca3af" : "#3b82f6",
                              shrink: 0, flexShrink: 0,
                            }}>
                              {done ? "✓" : locked ? "🔒" : "▶"}
                            </div>
                            <span style={{ flex: 1, fontSize: 13, color: darkMode ? "#e2e8f0" : "#374151" }}>
                              {lesson.title}
                              {lesson.free && !purchased && (
                                <span style={{
                                  marginLeft: 6, fontSize: 10, fontWeight: 700,
                                  background: "#d1fae5", color: "#065f46",
                                  padding: "1px 6px", borderRadius: 4,
                                }}>BEPUL</span>
                              )}
                            </span>
                            <span style={{ fontSize: 12, color: "#9ca3af" }}>{lesson.duration}</span>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}

          {/* Reviews tab */}
          {activeTab === "reviews" && <Reviews darkMode={darkMode} />}

          {/* FAQ tab */}
          {activeTab === "faq" && (
            <div>
              {faqs.map((faq, i) => {
                const [open, setOpen] = useState(false);
                return (
                  <div key={i} style={{ marginBottom: 8 }}>
                    <button
                      onClick={() => setOpen(!open)}
                      style={{
                        width: "100%", textAlign: "left",
                        padding: "13px 16px", borderRadius: open ? "10px 10px 0 0" : 10,
                        background: darkMode ? "#1e293b" : "#f8fafc",
                        border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                        cursor: "pointer", display: "flex", justifyContent: "space-between",
                      }}
                    >
                      <span style={{ fontWeight: 600, fontSize: 13, color: darkMode ? "#f1f5f9" : "#111" }}>{faq.q}</span>
                      <span style={{ color: "#6b7280", fontSize: 16 }}>{open ? "−" : "+"}</span>
                    </button>
                    {open && (
                      <div style={{
                        padding: "12px 16px",
                        background: darkMode ? "#0f172a" : "#fff",
                        border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
                        borderTop: "none", borderRadius: "0 0 10px 10px",
                        fontSize: 13, color: darkMode ? "#94a3b8" : "#4b5563", lineHeight: 1.7,
                      }}>
                        {faq.a}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Right — sticky CTA */}
        <div style={{ width: 260, flexShrink: 0 }}>
          <div style={{
            position: "sticky", top: 84,
            background: darkMode ? "#1e293b" : "#fff",
            borderRadius: 16, border: `1px solid ${darkMode ? "#334155" : "#e5e7eb"}`,
            padding: "20px", boxShadow: "0 4px 24px rgba(0,0,0,0.1)",
          }}>
            <p style={{ margin: "0 0 4px", fontSize: 24, fontWeight: 800, color: purchased ? "#10b981" : "#3b82f6" }}>
              {course.price === 0 ? "Bepul" : course.price.toLocaleString() + " so'm"}
            </p>
            {!purchased && course.price > 0 && (
              <p style={{ margin: "0 0 14px", fontSize: 11, color: "#6b7280" }}>
                Bir martalik to'lov · Umrbod kirish
              </p>
            )}

            {purchased ? (
              <div style={{
                padding: "10px 14px", borderRadius: 10, marginBottom: 14,
                background: "#d1fae5", textAlign: "center",
              }}>
                <p style={{ margin: 0, fontSize: 13, fontWeight: 600, color: "#065f46" }}>
                  ✅ Kursga yozilgansiz
                </p>
                <p style={{ margin: "4px 0 0", fontSize: 12, color: "#065f46" }}>
                  Progress: {progress}%
                </p>
              </div>
            ) : (
              <button
                onClick={() => course.price === 0 ? setPurchased(true) : setShowPayment(true)}
                style={{
                  width: "100%", padding: "13px 0", marginBottom: 10,
                  background: "#3b82f6", color: "#fff",
                  border: "none", borderRadius: 10,
                  fontSize: 14, fontWeight: 700, cursor: "pointer",
                }}
              >
                {course.price === 0 ? "🆓 Bepul Boshlash" : "💳 Sotib Olish"}
              </button>
            )}

            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {[
                { icon: "⏱", text: `${course.duration} soat video` },
                { icon: "📱", text: "Mobil va kompyuter" },
                { icon: "♾️", text: "Umrbod kirish" },
                { icon: "🏆", text: "Tugatish sertifikati" },
                { icon: "🔄", text: "30 kunlik qaytarish" },
              ].map((item, i) => (
                <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 14 }}>{item.icon}</span>
                  <span style={{ fontSize: 12, color: darkMode ? "#94a3b8" : "#6b7280" }}>{item.text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {showPayment && (
        <PaymentModal
          course={course}
          onClose={() => setShowPayment(false)}
          onSuccess={() => { setPurchased(true); showToast("Kursga muvaffaqiyatli yozildingiz! 🎉", "success"); }}
          darkMode={darkMode}
        />
      )}
    </div>
  );
};

export default CourseDetail;

